#!/usr/bin/env bash
# =============================================================================
#  Two-tier Docker Swarm demo
#    web  service -> MANAGER node, publishes :8080 (browser form + JSON API)
#    db   service -> WORKER  node, Postgres with a persistent volume
#  Data typed in the browser is written across the overlay into the worker's DB.
#
#  Run ON THE MANAGER, AFTER the swarm is formed (swarm init + worker join).
#      bash deploy.sh
# =============================================================================
set -euo pipefail

NET=app-net
SUBNET=10.20.0.0/24
DB_NAME=appdb
DB_USER=appuser
DB_PASS=apppass
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

# --- app source (embedded) --------------------------------------------------
echo '' | base64 -d > "$WORK/app.py"
echo ">> wrote app.py ($(wc -c < "$WORK/app.py") bytes)"

# --- must be a manager ------------------------------------------------------
if ! docker node ls >/dev/null 2>&1; then
  echo "!! This node is not a swarm manager. Run 'docker swarm init' first"
  echo "   (and join your worker) — see README.md → Prerequisites."
  exit 1
fi

# --- overlay network --------------------------------------------------------
if docker network inspect "$NET" >/dev/null 2>&1; then
  echo ">> network $NET already exists"
else
  echo ">> creating overlay network $NET ($SUBNET)"
  docker network create --driver overlay --subnet "$SUBNET" "$NET"
fi

# --- label nodes ------------------------------------------------------------
MANAGER_ID="$(docker info -f '{{.Swarm.NodeID}}')"
WORKER_ID="$(docker node ls --filter role=worker -q | head -n1 || true)"
echo ">> labelling manager $MANAGER_ID role=manager"
docker node update --label-add role=manager "$MANAGER_ID" >/dev/null
if [ -n "$WORKER_ID" ]; then
  echo ">> labelling worker  $WORKER_ID role=worker"
  docker node update --label-add role=worker "$WORKER_ID" >/dev/null
  DB_CONSTRAINT='node.labels.role==worker'
else
  echo "!! no worker node found — pinning db to the manager (single-node fallback)"
  DB_CONSTRAINT='node.labels.role==manager'
fi

# --- clean previous run -----------------------------------------------------
echo ">> removing any previous web/db services + config"
docker service rm web db >/dev/null 2>&1 || true
for _ in $(seq 1 15); do
  docker service ls --format '{{.Name}}' | grep -qE '^(web|db)$' || break
  sleep 1
done
sleep 2
docker config rm web-app >/dev/null 2>&1 || true
docker config create web-app "$WORK/app.py" >/dev/null

# --- db service (worker) ----------------------------------------------------
echo ">> creating db service ($DB_CONSTRAINT)"
docker service create --name db \
  --constraint "$DB_CONSTRAINT" \
  --network "$NET" \
  --env POSTGRES_DB="$DB_NAME" \
  --env POSTGRES_USER="$DB_USER" \
  --env POSTGRES_PASSWORD="$DB_PASS" \
  --mount type=volume,source=db-data,target=/var/lib/postgresql/data \
  postgres:16-alpine >/dev/null

# --- web service (manager) --------------------------------------------------
echo ">> creating web service (manager, :8080)"
docker service create --name web \
  --constraint 'node.labels.role==manager' \
  --network "$NET" \
  --publish published=8080,target=80 \
  --env DB_HOST=db \
  --env DB_NAME="$DB_NAME" \
  --env DB_USER="$DB_USER" \
  --env DB_PASSWORD="$DB_PASS" \
  --config source=web-app,target=/app/app.py \
  python:3.11-slim \
  sh -c "pip install --no-cache-dir --disable-pip-version-check -q psycopg2-binary && python /app/app.py" >/dev/null

IP="$(hostname -I 2>/dev/null | awk '{print $1}')"
echo
echo "=============================================================="
echo " Deployed.  web -> :8080 (manager)   db -> Postgres (worker)"
echo "--------------------------------------------------------------"
echo " Open the form in a browser:"
echo "   http://${IP:-<manager-ip>}:8080"
echo " JSON view (any host, curl):"
echo "   curl http://${IP:-<manager-ip>}:8080/api/messages"
echo "--------------------------------------------------------------"
echo " web needs ~20-40s on first start (pip install + db warmup)."
echo " Watch:  docker service ls ; docker service ps web db"
echo " Logs :  docker service logs -f web"
echo "=============================================================="
